"use strict";(self.webpackChunkglasskube_dev=self.webpackChunkglasskube_dev||[]).push([["3206"],{8888:function(e,t,n){n.r(t),n.d(t,{assets:()=>l,contentTitle:()=>r,default:()=>c,frontMatter:()=>i,metadata:()=>o,toc:()=>d});var o=n(72790),a=n(62615),s=n(14595);let i={slug:"kubernetes-zero-downtime-deployments-aws-eks",title:"Zero-Downtime Kubernetes Deployments on AWS with EKS",description:"Zero-downtime deployments on Kubernetes on AWS EKS utilizing Pod Readiness Gates, graceful application shutdown and termination delays with code examples in Go",authors:["kosmoz"],tags:["AWS","Kubernetes","DevOps","EKS","Pod Readiness Gates","Golang"],image:"/img/blog/2025-03-03-aws-eks-0-downtime/aws-eks-zero-downtime-deployments.png"},r,l={authorsImageUrls:[void 0]},d=[{value:"Background: How do Load Balancers Work in Kubernetes on AWS with EKS",id:"background-how-do-load-balancers-work-in-kubernetes-on-aws-with-eks",level:2},{value:"Testing Zero-downtime deployments",id:"testing-zero-downtime-deployments",level:2},{value:"How we achieved Zero-downtime deployments in three parts",id:"how-we-achieved-zero-downtime-deployments-in-three-parts",level:2},{value:"Part 1: Using Pod Readiness Gate on AWS EKS",id:"part-1-using-pod-readiness-gate-on-aws-eks",level:3},{value:"Part 2: Graceful Application Shutdown in Go",id:"part-2-graceful-application-shutdown-in-go",level:3},{value:"Part 3: Kubernetes Termination Delay with Sidecars for Go applications",id:"part-3-kubernetes-termination-delay-with-sidecars-for-go-applications",level:3},{value:"Conclusion",id:"conclusion",level:2}];function h(e){let t={a:"a",blockquote:"blockquote",code:"code",em:"em",h2:"h2",h3:"h3",img:"img",li:"li",ol:"ol",p:"p",pre:"pre",...(0,s.R)(),...e.components};return(0,a.jsxs)(a.Fragment,{children:[(0,a.jsxs)(t.p,{children:["I am Jakob\u2014an engineer working at Glasskube, which helps companies distribute their application to customer-controlled environments.\nWe build an Open Source Software Distribution platform called Distr (",(0,a.jsx)(t.a,{href:"https://github.com/glasskube/distr",children:(0,a.jsx)(t.code,{children:"github.com/glasskube/distr"})}),"),\nthe ",(0,a.jsx)(t.a,{href:"https://signup.distr.sh/",children:"hosted version"})," of which is running on AWS EKS."]}),"\n",(0,a.jsxs)(t.p,{children:["If you have ever hosted a web-application on EKS, Amazon's managed Kubernetes offering, you are most-likely familiar with the AWS Load Balancer Controller project (formerly AWS ALB Ingress Controller).\nIf you have also ",(0,a.jsx)(t.em,{children:"upgraded"})," that application, you might also be familiar with reports like this:"]}),"\n",(0,a.jsx)(t.p,{children:(0,a.jsx)(t.img,{alt:"502 error report",src:n(15161).A+"",width:"500",height:"51"})}),"\n",(0,a.jsx)(t.p,{children:"The upgrade you just triggered has caused downtime for your application!\nYou might think that there is an error your application, but all your logs and metrics seem to indicate that it's doing just fine.\nThe truth is that although the AWS Load Balancer Controller is a fantastic piece of software, it is surprisingly tricky to roll out releases without downtime."}),"\n",(0,a.jsx)(t.p,{children:"In this blog post I will share what we have learned in the process of achieving this goal, hopefully in a way that you can adapt to your own application.\nBut before getting to the solution, let's take a look under the hood and learn how the AWS Load Balancer Controller actually works."}),"\n",(0,a.jsx)(t.h2,{id:"background-how-do-load-balancers-work-in-kubernetes-on-aws-with-eks",children:"Background: How do Load Balancers Work in Kubernetes on AWS with EKS"}),"\n",(0,a.jsxs)(t.p,{children:["In Kubernetes, usually every pod has its own IP address.\nThis IP address can be used to communicate with a server application running in that pod via the clusters' internal network.\nIn most cases, however, this IP is ",(0,a.jsx)(t.em,{children:"not"})," publicly routable, so to make your server application available to the public, you need to either expose your service via a Kubernetes service with type ",(0,a.jsx)(t.code,{children:"NodePort"})," or, more commonly, via an ",(0,a.jsx)(t.code,{children:"Ingress"})," or a Kubernetes service with type ",(0,a.jsx)(t.code,{children:"LoadBalancer"}),".\nBoth of these options are similar in the sense that Kubernetes doesn't normally come with a solution to reconcile these resources out of the box.\nSo, if your managed Kubernetes distribution does not come with built-in support via their Cloud Controller Manager implementation, or you are running an unmanaged Kubernetes cluster, you will have to install your own implementations of these features."]}),"\n",(0,a.jsxs)(t.p,{children:["For this blog post we will focus on AWS EKS, where the AWS Load Balancer Controller is the canonical way to handle both Ingress and LoadBalancer resources.\nIt automatically maps Ingress resources to AWS Application Load Balancers and LoadBalancer services to AWS Network Load Balancers.\nIn both cases, it creates a ",(0,a.jsx)(t.code,{children:"TargetGroupBinding"})," that represents the target group in the AWS ecosystem and watches the services ",(0,a.jsx)(t.code,{children:"Endpoint"})," resource to update the target group with the IPs from the ",(0,a.jsx)(t.code,{children:"Endpoint"}),".\nAn ",(0,a.jsx)(t.code,{children:"Endpoint"}),' is created by Kubernetes for each service, and it tracks which IP addresses are routable via that service.\nThe endpoint controller uses several signals to determine whether pod is eligible to be part of an endpoint, including container probes and whether the pod is marked as "terminating".']}),"\n",(0,a.jsx)(t.p,{children:(0,a.jsx)(t.img,{alt:"aws load balancer diagram",src:n(30757).A+"",width:"2256",height:"1268"})}),"\n",(0,a.jsx)(t.p,{children:'From the above, it follows that the AWS Load Balancer Controller simply adds missing IP addresses to the target group and removes superfluous ones, but unfortunately, both of those actions take some time which can lead to downtime in subtle ways.\nAfter an IP address is added to the target group, the AWS system starts performing its own health check, which is completely unrelated to the Pod\'s container probes.\nOnly once this health check indicates that the target is healthy, will the Load Balancer start routing traffic to that target.\nBut because Kubernetes doesn\'t know about this external health check, it continues to replace other replicas of the workload which can lead to a situation where all pods have been replaced, but none are considered "healthy" by the Load Balancer yet.\nConversely, if a Pod is marked as "terminating", it takes about 5-15 seconds for the AWS Load Balancer Controller to register this change and the Load Balancer to drain the target.\nBut if the application has already terminated, it might still try to route some requests to this target, which results in a 502 or 504 HTTP error for the client.'}),"\n",(0,a.jsx)(t.p,{children:'A 502 HTTP error code stands for "Bad Gateway", which, in our case, means that the load balancer was not able to get a valid HTTP response from a target, either because no target is available, the target sent an invalid response or no response at all.\nA 504 HTTP error code on the other hand stands of "Gateway Timeout", which means that the target didn\'t send a response in time.\nThis is exactly what had happened when I took the screenshot in the introduction.'}),"\n",(0,a.jsxs)(t.p,{children:["Fortunately, both of those issues can be worked around, but the ",(0,a.jsx)(t.a,{href:"https://docs.aws.amazon.com/eks/latest/best-practices/load-balancing.html#_availability_and_pod_lifecycle",children:"documentation"})," is a little nebulous about how everything works in detail."]}),"\n",(0,a.jsx)(t.h2,{id:"testing-zero-downtime-deployments",children:"Testing Zero-downtime deployments"}),"\n",(0,a.jsxs)(t.p,{children:["In what follows, I will describe several solutions to the issues outlined above, all of which are necessary to solve one part of the general problem.\nIf you follow along, implementing these solutions for your own application, I suggest testing your changes after each iteration using ",(0,a.jsx)(t.a,{href:"https://github.com/JoeDog/siege",children:(0,a.jsx)(t.code,{children:"siege"})}),".\nSiege is an HTTP load testing utility that is perfect for our use-case.\nIt lets you define how many requests it sends to your server, shows you the status code of each request and prints a nice summary at the end.\nIt can be invoked like ",(0,a.jsx)(t.code,{children:"siege -c 2 https://your-application.example.com"}),", where ",(0,a.jsx)(t.code,{children:"-c 2"})," tells it to perform 2 requests in parallel."]}),"\n",(0,a.jsx)(t.h2,{id:"how-we-achieved-zero-downtime-deployments-in-three-parts",children:"How we achieved Zero-downtime deployments in three parts"}),"\n",(0,a.jsx)(t.h3,{id:"part-1-using-pod-readiness-gate-on-aws-eks",children:"Part 1: Using Pod Readiness Gate on AWS EKS"}),"\n",(0,a.jsxs)(t.p,{children:["The first issue (pods being cycled too quickly by Kubernetes) has, arguably, the easiest solution.\nKubernetes supports adding extra pod status conditions by the use of ",(0,a.jsx)(t.a,{href:"https://kubernetes.io/docs/concepts/workloads/pods/pod-lifecycle/#pod-readiness-gate",children:"Pod Readiness Gates"}),".\nThese readiness gates are considered for workload availability in addition to the container probes built-in to Kubernetes.\nFor a ",(0,a.jsx)(t.code,{children:"Deployment"})," this has the effect that during a ",(0,a.jsx)(t.code,{children:"RollingUpdate"})," rollout the Deployment controller will not scale down the old ",(0,a.jsx)(t.code,{children:"ReplicaSet"}),' any further until the new Pod has a readiness gate indicating that it is "ready".\nThe AWS Load Balancer Controller ',(0,a.jsx)(t.a,{href:"https://kubernetes-sigs.github.io/aws-load-balancer-controller/v2.2/deploy/pod_readiness_gate/",children:"supports"})," adding readiness gates to relevant pods to indicate the load balancer health check status.\nThis can be enabled by simply labeling the ",(0,a.jsx)(t.code,{children:"Namespace"})," where the pods are situated with ",(0,a.jsx)(t.code,{children:"elbv2.k8s.aws/pod-readiness-gate-inject=enabled"}),".\nIf you do this, you will notice that Kubernetes will wait for a while before starting to terminate the next pod as it waits for the first one to become ready.\nTo show readiness gates using ",(0,a.jsx)(t.code,{children:"kubectl"})," you can use ",(0,a.jsx)(t.code,{children:"kubectl get pods -o wide"}),"."]}),"\n",(0,a.jsx)(t.h3,{id:"part-2-graceful-application-shutdown-in-go",children:"Part 2: Graceful Application Shutdown in Go"}),"\n",(0,a.jsxs)(t.p,{children:["This part does not directly relate to one of the issues above, and it is relevant not only to the AWS ecosystem.\nTo minimize downtime, your web server must not terminate immediately when instructed to do so by the operating system.\nThe solution described here applies to applications written in Go, using the standard library ",(0,a.jsx)(t.code,{children:"http"})," module for serving and listening.\nTake a look at the following example web application:"]}),"\n",(0,a.jsx)(t.pre,{children:(0,a.jsx)(t.code,{className:"language-go",children:'package main\n\nimport (\n	"fmt"\n	"log"\n	"net/http"\n)\n\nfunc main() {\n	if err := http.ListenAndServe(":8080", MyAppRouter()); err != nil {\n		log.Fatal(err)\n	}\n}\n\nfunc MyAppRouter() http.HandlerFunc {\n	return func(w http.ResponseWriter, r *http.Request) {\n		fmt.Print(w, "Hello world!")\n	}\n}\n'})}),"\n",(0,a.jsx)(t.p,{children:"This shows the most common way to start a web server in Go, but it does not shut down gracefully.\nAt the very least, it has to wait for ongoing request handlers to finish, gracefully terminate long-standing connections.\nA more complex application should probably also close all connections to databases, synchronize logs and more."}),"\n",(0,a.jsxs)(t.p,{children:["By creating an ",(0,a.jsx)(t.code,{children:"http.Server"})," instance and handling the termination signal, you can easily trigger a graceful shutdown of the server.\nIntuitively, you might build something like this:"]}),"\n",(0,a.jsx)(t.pre,{children:(0,a.jsx)(t.code,{className:"language-go",children:'func main() {\n	srv := http.Server{Addr: ":8080", Handler: MyAppRouter()}\n\n	go OnSigterm(func() {\n		if err := srv.Shutdown(context.TODO()); err != nil {\n			log.Fatal(err)\n		}\n	})\n\n	if err := srv.ListenAndServe(); err != nil {\n		log.Fatal(err)\n	}\n}\n\nfunc OnSigterm(callback func()) {\n	sigint := make(chan os.Signal, 1)\n	signal.Notify(sigint, syscall.SIGTERM, syscall.SIGINT)\n	<-sigint\n	callback()\n}\n'})}),"\n",(0,a.jsxs)(t.p,{children:["While the above does ",(0,a.jsx)(t.em,{children:"look"})," correct, it doesn't actually help with the problem at all.\nIf you carefully read the documentation for the ",(0,a.jsx)(t.code,{children:"net/http"})," package you will see this:"]}),"\n",(0,a.jsxs)(t.blockquote,{children:["\n",(0,a.jsx)(t.p,{children:"When Shutdown is called, Serve, ListenAndServe, and ListenAndServeTLS immediately return ErrServerClosed. Make sure the program doesn't exit and waits instead for Shutdown to return."}),"\n"]}),"\n",(0,a.jsx)(t.p,{children:"Oops!\nThis means we have to do two additional things:"}),"\n",(0,a.jsxs)(t.ol,{children:["\n",(0,a.jsxs)(t.li,{children:["Catch the ",(0,a.jsx)(t.code,{children:"ErrServerClosed"})," returned in this case"]}),"\n",(0,a.jsxs)(t.li,{children:["Only exit after ",(0,a.jsx)(t.code,{children:"Shutdown"})," has completed"]}),"\n"]}),"\n",(0,a.jsx)(t.p,{children:"Fortunately, the first task is trivial, and the second can be easily accomplished by using a Go channel:"}),"\n",(0,a.jsx)(t.pre,{children:(0,a.jsx)(t.code,{className:"language-go",children:'func main() {\n	srv := http.Server{Addr: ":8080", Handler: MyAppRouter()}\n\n	shutdownComplete := make(chan struct{})\n	go OnSigterm(func() {\n		if err := srv.Shutdown(context.TODO()); err != nil {\n			log.Fatal(err)\n		}\n		close(shutdownComplete)\n	})\n\n	if err := srv.ListenAndServe(); err != nil && err != http.ErrServerClosed {\n		log.Fatal(err)\n	}\n	<-shutdownComplete\n}\n'})}),"\n",(0,a.jsx)(t.p,{children:"After applying this fix, I was personally very excited to try this improved shutdown procedure, but was disappointed to find that it almost didn't help at all:"}),"\n",(0,a.jsx)(t.p,{children:(0,a.jsx)(t.img,{alt:"siege report with errors",src:n(14747).A+"",width:"532",height:"333"})}),"\n",(0,a.jsx)(t.p,{children:'You can also see this in the AWS UI for target group monitoring as the "Target connection errors" metric'}),"\n",(0,a.jsx)(t.p,{children:(0,a.jsx)(t.img,{alt:"aws target group metrics showing errors",src:n(46174).A+"",width:"1630",height:"1025"})}),"\n",(0,a.jsxs)(t.p,{children:["The reason for this is obvious in hindsight, and attentive readers of this blog post might already have figured it out:\nThe AWS Load Balancer keeps sending ",(0,a.jsx)(t.em,{children:"new"})," requests to the target for several seconds ",(0,a.jsx)(t.em,{children:"after"})," the application is sent the termination signal!\nSo, in order to actually fix issue number two from above, you have to make your application wait for some time after receiving the termination signal before initiating graceful shutdown."]}),"\n",(0,a.jsx)(t.h3,{id:"part-3-kubernetes-termination-delay-with-sidecars-for-go-applications",children:"Part 3: Kubernetes Termination Delay with Sidecars for Go applications"}),"\n",(0,a.jsxs)(t.p,{children:['As alluded to before, it usually takes 5-15 seconds for the endpoint change to fully propagate to the target group.\nSince you can not be sure how long it will actually take, determining the amount of time to wait is kind of a balancing act between safety margin and rollout speed.\nI would recommend a value between 20 and 30 seconds, since anything below that might risk terminating too early and everything above seems excessive.\nThe canonical way to achieve such a "shutdown delay" in Kubernetes without modifying your applications code is to add a ',(0,a.jsx)(t.code,{children:"preStop"})," lifecycle hook to your pod template definition.\nThat usually looks something like this:"]}),"\n",(0,a.jsx)(t.pre,{children:(0,a.jsx)(t.code,{className:"language-yaml",children:"apiVersion: apps/v1\nkind: Deployment\nmetadata:\n  name: myapp\nspec:\n  template:\n    spec:\n      terminationGracePeriodSeconds: 40\n      containers:\n        - name: my-app\n          # ...\n          lifecycle:\n            preStop:\n              exec:\n                command: [sh, -c, 'sleep 20']\n"})}),"\n",(0,a.jsxs)(t.p,{children:["If your application's container image uses a full base image such as ubuntu, debian or alpine, you should definitely go with this approach.\nHowever, a pattern that is becoming more and more common is the use of distroless base images.\nThese base images don't contain the typical GNU coreutils or even a shell, so the ",(0,a.jsx)(t.code,{children:"preStop"})," lifecycle hook cannot be used as described above."]}),"\n",(0,a.jsxs)(t.p,{children:["After carefully reading the Kubernetes documentation on the topic of ",(0,a.jsx)(t.a,{href:"https://kubernetes.io/docs/concepts/workloads/pods/pod-lifecycle/#pod-termination",children:"Pod termination"}),",\nyou might be tempted to add a sidecar container with a ",(0,a.jsx)(t.code,{children:"preStop"})," lifecycle hook to your deployment to stop your application to be terminated too quickly."]}),"\n",(0,a.jsx)(t.pre,{children:(0,a.jsx)(t.code,{className:"language-yaml",children:"- name: busybox\n  image: busybox\n  command:\n    - sh\n    - -c\n    - |\n      trap 'echo signal received' TERM INT\n      echo waiting for signal\n      sleep 9999999999d & wait || exit 0\n  lifecycle:\n    preStop:\n      exec:\n        command: [sh, -c, 'sleep 20']\n"})}),"\n",(0,a.jsxs)(t.p,{children:["Unfortunately, after lots of trial and error, I have found that this does not work.\nAlthough your application container keeps running until the Kubelet sends the termination signal to all your containers, the ports are immediately closed as soon as the pod enters the ",(0,a.jsx)(t.code,{children:"Terminating"}),' phase, even though the underlying application remains in the "ready" state until it receives the termination signal after the ',(0,a.jsx)(t.code,{children:"preStop"})," lifecycle hook of the sidecar container has finished."]}),"\n",(0,a.jsxs)(t.p,{children:["In those cases, your only option is to bake this feature directly into your application. You can either stick with the ",(0,a.jsx)(t.code,{children:"preStop"})," lifecycle hook idea and implement something like a sleep sub-command or HTTP endpoint, or (my preferred solution) allow your application to wait for some time before shutting down the server.\nThis is easy enough to accomplish in most programming languages. In Go you just have to call ",(0,a.jsx)(t.code,{children:"time.Sleep"})," with the desired duration."]}),"\n",(0,a.jsx)(t.pre,{children:(0,a.jsx)(t.code,{className:"language-go",children:'var terminationDelay = 20 * time.Second\n\nfunc main() {\n	srv := http.Server{Addr: ":8080", Handler: MyAppRouter()}\n\n	shutdownComplete := make(chan struct{})\n	go OnSigterm(func() {\n		time.Sleep(terminationDelay)\n		if err := srv.Shutdown(context.TODO()); err != nil {\n			log.Fatal(err)\n		}\n		close(shutdownComplete)\n	})\n\n	if err := srv.ListenAndServe(); err != nil && err != http.ErrServerClosed {\n		log.Fatal(err)\n	}\n	<-shutdownComplete\n}\n'})}),"\n",(0,a.jsx)(t.p,{children:"If you deploy this application and test the rolling update, you will see that there are no more 502/504 errors.\nWe have achieved 100% downtime-free deployments!"}),"\n",(0,a.jsx)(t.p,{children:(0,a.jsx)(t.img,{alt:"siege report with no errors",src:n(99118).A+"",width:"556",height:"324"})}),"\n",(0,a.jsx)(t.h2,{id:"conclusion",children:"Conclusion"}),"\n",(0,a.jsxs)(t.p,{children:["In this blog post we learned how to deploy on AWS EKS with zero-downtime by enabling Pod Readiness Gates and implementing graceful shutdown as well as a termination delay.\nBut in addition to this, I hope that, like me, you were able to learn something about how external load balancers work in Kubernetes.\nTo me, it's always interesting to take a look below the surface of a complex system, this time learning about ",(0,a.jsx)(t.code,{children:"Endpoints"}),", ",(0,a.jsx)(t.code,{children:"EndpointSlices"}),", ",(0,a.jsx)(t.code,{children:"TargetGroupBindings"})," and so much more, and I'm sure this knowledge will be very useful in the future.\nIf you want to see a real-world implementation of these features, check out Distr (",(0,a.jsx)(t.a,{href:"https://github.com/glasskube/distr",children:(0,a.jsx)(t.code,{children:"github.com/glasskube/distr"})}),"), our Open Source Software Distribution Platform!"]})]})}function c(e={}){let{wrapper:t}={...(0,s.R)(),...e.components};return t?(0,a.jsx)(t,{...e,children:(0,a.jsx)(h,{...e})}):h(e)}},15161:function(e,t,n){n.d(t,{A:()=>o});let o="data:image/png;base64,"},30757:function(e,t,n){n.d(t,{A:()=>o});let o=n.p+"assets/images/aws-loadbalancer-b40049db854fc86cafd09fb995e0c233.png"},14747:function(e,t,n){n.d(t,{A:()=>o});let o=n.p+"assets/images/fail-deee402e73aa26dea9416c10d8fe9e1b.png"},99118:function(e,t,n){n.d(t,{A:()=>o});let o=n.p+"assets/images/success-9d5f37fca60238a771b76faa59e66fa3.png"},46174:function(e,t,n){n.d(t,{A:()=>o});let o=n.p+"assets/images/target-group-metrics-349bfbbc8db6bc55f4ccd5ce4d74ff07.png"},14595:function(e,t,n){n.d(t,{R:()=>i,x:()=>r});var o=n(59471);let a={},s=o.createContext(a);function i(e){let t=o.useContext(s);return o.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:i(e.components),o.createElement(s.Provider,{value:t},e.children)}},72790:function(e){e.exports=JSON.parse('{"permalink":"/zh-Hans/blog/kubernetes-zero-downtime-deployments-aws-eks","source":"@site/blog/2025-03-03-aws-eks-0-downtime/index.md","title":"Zero-Downtime Kubernetes Deployments on AWS with EKS","description":"Zero-downtime deployments on Kubernetes on AWS EKS utilizing Pod Readiness Gates, graceful application shutdown and termination delays with code examples in Go","date":"2025-03-03T00:00:00.000Z","tags":[{"inline":true,"label":"AWS","permalink":"/zh-Hans/blog/tags/aws"},{"inline":true,"label":"Kubernetes","permalink":"/zh-Hans/blog/tags/kubernetes"},{"inline":true,"label":"DevOps","permalink":"/zh-Hans/blog/tags/dev-ops"},{"inline":true,"label":"EKS","permalink":"/zh-Hans/blog/tags/eks"},{"inline":true,"label":"Pod Readiness Gates","permalink":"/zh-Hans/blog/tags/pod-readiness-gates"},{"inline":true,"label":"Golang","permalink":"/zh-Hans/blog/tags/golang"}],"readingTime":11.59,"hasTruncateMarker":true,"authors":[{"name":"Jakob Steiner","title":"Software Engineer","url":"https://github.com/kosmoz","imageURL":"https://avatars.githubusercontent.com/kosmoz","key":"kosmoz","page":null}],"frontMatter":{"slug":"kubernetes-zero-downtime-deployments-aws-eks","title":"Zero-Downtime Kubernetes Deployments on AWS with EKS","description":"Zero-downtime deployments on Kubernetes on AWS EKS utilizing Pod Readiness Gates, graceful application shutdown and termination delays with code examples in Go","authors":["kosmoz"],"tags":["AWS","Kubernetes","DevOps","EKS","Pod Readiness Gates","Golang"],"image":"/img/blog/2025-03-03-aws-eks-0-downtime/aws-eks-zero-downtime-deployments.png"},"unlisted":false,"prevItem":{"title":"We built an MCP Gateway because nothing else worked","permalink":"/zh-Hans/blog/distr-mcp-server"},"nextItem":{"title":"We switched from Java to Go and don\'t regret it","permalink":"/zh-Hans/blog/from-java-to-go"}}')}}]);